corrected_code:
export const clinicalRouter = router({
  updateDosageInstructions: protectedProcedure
    .input(z.object({ prescriptionId: z.string(), instructions: z.string().max(500) }))
    .mutation(async ({ input, ctx }) => {
      const rx = await ctx.prisma.prescription.findFirst({
        where: { id: input.prescriptionId, prescribingDoctorId: ctx.user.id },
      });
      if (!rx) throw new TRPCError({ code: 'FORBIDDEN', message: 'Only the prescribing physician can modify dosage instructions' });
      return await ctx.prisma.prescription.update({
        where: { id: input.prescriptionId },
        data: { dosageInstructions: input.instructions },
      });
    }),
});
